async function load(){
 const version=++loadVersion,owner=user?.id;if(!owner)return;
 if(demo){records=JSON.parse(localStorage.getItem('dk-klusbeheer-demo-v1')||'null')||seed();loadFailed=false;render();return}
 try{const all=[];for(let offset=0;;offset+=1000){const {data:rows,error}=await sb.from('klusbeheer_records').select('*').eq('owner_id',user.id).order('created_at',{ascending:true}).order('id',{ascending:true}).range(offset,offset+999);if(error)throw error;all.push(...rows);if(rows.length<1000)break}if(version!==loadVersion||owner!==user?.id)return;records=all;loadFailed=false;render()}
 catch(err){if(version!==loadVersion||owner!==user?.id)return;loadFailed=true;render();toast('Laden mislukt: '+err.message,true)}
}
async function write(type,values,existing=null,projectId=null){
 if(loadFailed)throw Error('Laad eerst de gegevens opnieuw.');
 const owner=user?.id;if(!owner)throw Error('Log opnieuw in.');const payload={...data(existing),...values};
 if(existing && !records.some(r=>r.id===existing.id))throw Error('Deze regel bestaat niet meer. Herlaad de pagina.');
 if(demo){const now=new Date().toISOString();if(existing){existing.data=payload;if(['materiaal','uur','calculatie'].includes(type)&&values.project_id)existing.project_legacy_id=values.project_id;existing.updated_at=now}else records.push({id:uuid(),legacy_id:uuid(),owner_id:user.id,record_type:type,project_legacy_id:projectId||null,data:payload,created_at:now,updated_at:now});localStorage.setItem('dk-klusbeheer-demo-v1',JSON.stringify(records));return}
 if(existing){let q=sb.from('klusbeheer_records').update({data:payload,updated_at:new Date().toISOString(),...(['materiaal','uur','calculatie'].includes(type)&&values.project_id?{project_legacy_id:values.project_id}:{})}).eq('id',existing.id).eq('owner_id',user.id);q=existing.updated_at?q.eq('updated_at',existing.updated_at):q.is('updated_at',null);const {data:rows,error}=await q.select();if(error)throw error;if(owner!==user?.id)throw Error('Het ingelogde account is gewijzigd. Laad opnieuw.');if(rows.length!==1)throw Error('De regel is intussen gewijzigd. Herlaad voordat je opnieuw opslaat.');records=records.map(r=>r.id===existing.id?rows[0]:r)}
 else{const {data:rows,error}=await sb.from('klusbeheer_records').insert({owner_id:user.id,record_type:type,legacy_id:uuid(),project_legacy_id:projectId||values.project_id||null,data:payload}).select();if(error)throw error;if(owner!==user?.id)throw Error('Het ingelogde account is gewijzigd. Laad opnieuw.');if(rows.length!==1)throw Error('Opslaan kon niet worden bevestigd. Herlaad de administratie.');records.push(rows[0])}
}
