 const rows=t.showHours?original:[...original.filter(l=>l.kind!=='uur'),...(labor.length?[{name:'Arbeid',qty:1,price:round(labor.reduce((s,l)=>s+l.gross,0)),basis:'incl',net:round(labor.reduce((s,l)=>s+l.net,0)),gross:round(labor.reduce((s,l)=>s+l.gross,0)),vat:null}]:[])];
