function documentPreview(c){return stats([['Totaal incl. btw',c.unresolved.length?'Niet vastgesteld':money(c.gross)],['Btw',c.unresolved.length?'Niet vastgesteld':money(c.tax)]]);}
function orphanRecords(){return records.filter(r=>['materiaal','uur','calculatie'].includes(r.record_type)&&!isArchived(r)&&!find('project',projectIdOf(r)));}
function orphanLinkView(){const r=find(route.type,route.id);if(!r)return go('instellingen');shell('Klus koppelen',data(r).naam||data(r).omschrijving||route.type,`<div class="card compact"><form data-form="link-orphan">${select('project_id','Bestaande klus','',[['','Kies een klus'],...by('project').map(p=>[idOf(p),data(p).projectnaam])])}<p id="formerror" class="error" role="alert"></p><button type="submit">Koppeling opslaan</button>${button('Annuleren','go','data-page="instellingen"')}</form></div>`);}
function nextDocumentNumber(){
 const year=String(new Date().getFullYear()),pattern=new RegExp('^'+year+'-(\\d+)$');
 const used=by('factuur',true).map(r=>String(data(r).nummer||'').match(pattern)).filter(Boolean).map(m=>Number(m[1]));
 return year+'-'+String(Math.max(0,...used)+1).padStart(3,'0');
}
